<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiOrigin } from '../services/auth.js'
import OrderHistory from './OrderHistory.vue'
const props = defineProps({ session: { type: Object, required: true } })
const parts = new Intl.DateTimeFormat('en', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())
const part = key => parts.find(x => x.type === key).value
const today = `${part('year')}-${part('month')}-${part('day')}`
const from = ref(today.slice(0, 7) + '-01'), to = ref(today), branch = ref(''), mode = ref('ALL'), branches = ref([]), busy = ref(false), error = ref(''), data = ref(null)
const money = value => value == null ? 'Не визначено' : Number(value).toLocaleString('uk-UA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
const number = value => Number(value || 0).toLocaleString('uk-UA')
const truth = value => value === true || Number(value) === 1
const modes = { OWN: 'Власні філії', RESELLER: 'Філії посередників', UNSET: 'Тип не визначено' }
const periodCards = [['orders', 'Оформлено замовлень'], ['completed', 'Завершено позицій виробів'], ['issued', 'Видано позицій клієнтам']]
const currentCards = [['unfinished', 'Незавершені позиції'], ['waiting', 'Очікують майстра'], ['inProgress', 'Виготовляються'], ['late', 'Минув строк готовності'], ['approval', 'Потребують погодження ціни'], ['shortage', 'Мають дефіцит матеріалів'], ['awaitingBranch', 'Очікують приймання на філію'], ['readyPickup', 'На філії, готові до видачі']]
const branchSummary = computed(() => {
 const result = new Map()
 for (const r of data.value?.branches || []) { const key = `${r.branchNo}-${r.commerceMode}`; if (!result.has(key)) result.set(key, { ...r, orders: 0, completed: 0, issued: 0 }); result.get(key)[r.kind] = r.quantity }
 return [...result.values()].sort((a,b) => a.branchName.localeCompare(b.branchName, 'uk'))
})
async function api(path) { const response = await fetch(`${apiOrigin}/api/reports/management-overview${path}`, { headers: { Authorization: `Bearer ${props.session.token}` }, cache: 'no-store' }); const result = await response.json().catch(() => null); if (!response.ok) throw new Error(result?.message || `Не вдалося завантажити огляд (HTTP ${response.status})`); return result }
async function load() {
 if (busy.value) return
 if (!from.value || !to.value || from.value > to.value || to.value > today) { error.value = 'Перевірте період: кінець не пізніше сьогодні.'; return }
 busy.value = true; error.value = ''; data.value = null
 try { const params = new URLSearchParams({ from: from.value, to: to.value, mode: mode.value }); if (branch.value) params.set('branch', branch.value); data.value = await api('?' + params) } catch (e) { error.value = e.message } finally { busy.value = false }
}
function quick(value) { if (busy.value) return; to.value = today; from.value = value === 'today' ? today : today.slice(0, 7) + '-01'; load() }
onMounted(async () => { try { branches.value = await api('/branches'); await load() } catch (e) { error.value = e.message } })
</script>
<template><section class="management"><header><div><h2>Огляд керівника</h2><p>Результати за період та поточні питання підприємства.</p></div><div class="actions"><button type="button" :disabled="busy" @click="quick('today')">Сьогодні</button><button type="button" :disabled="busy" @click="quick('month')">Цей місяць</button></div></header><form class="filters" @submit.prevent="load"><label>Від<input v-model="from" type="date" :max="to" :disabled="busy" required></label><label>До включно<input v-model="to" type="date" :min="from" :max="today" :disabled="busy" required></label><label>Філія<select v-model="branch" :disabled="busy"><option value="">Усі філії</option><option v-for="b in branches" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label>Тип замовлень<select v-model="mode" :disabled="busy"><option value="ALL">Усі</option><option value="OWN">Власні філії</option><option value="RESELLER">Філії посередників</option></select></label><button :disabled="busy">{{ busy ? 'Завантаження…' : 'Показати / оновити' }}</button></form><p v-if="error" role="alert">{{ error }}</p><template v-if="data"><p class="context">Період: {{ data.from }} — {{ data.to }} · {{ modes[data.mode] || 'Усі типи' }} · {{ branches.find(b => Number(b.id) === Number(data.branch))?.name || 'Усі філії' }}</p><h3>За вибраний період</h3><div class="metrics"><article v-for="[key,label] in periodCards" :key="key"><span>{{ label }}</span><strong>{{ number(data.period[key]) }}</strong></article></div><p class="help">Завершення та видача рахуються один раз, за першою відповідною подією. Це різні групи замовлень, а не відсоток виконання нових. Одна картка виробу — одна позиція, незалежно від кількості примірників.</p><details><summary>Порівняти філії за період</summary><p v-if="!branchSummary.length">Подій за цей період немає.</p><div class="branch-grid"><article v-for="b in branchSummary" :key="`${b.branchNo}-${b.commerceMode}`"><h4>{{ b.branchName }}</h4><small>{{ modes[b.commerceMode] || b.commerceMode }}</small><p>Замовлення: <strong>{{ number(b.orders) }}</strong> · завершені позиції: <strong>{{ number(b.completed) }}</strong> · видані: <strong>{{ number(b.issued) }}</strong></p></article></div></details><h3>Поточний стан</h3><p>На {{ new Date(data.asOf).toLocaleString('uk-UA') }}. Фільтри філії й типу діють; вибраний період на ці черги не впливає.</p><div class="metrics"><article v-for="[key,label] in currentCards" :key="key" :class="{ attention: ['late','approval','shortage'].includes(key) && Number(data.current[key]) > 0 }"><span>{{ label }}</span><strong>{{ number(data.current[key]) }}</strong></article></div><p class="help">Показники можуть перетинатися: одна позиція може одночасно чекати погодження та мати дефіцит. Скасовані замовлення виключено; зупинені вироби не входять у незавершену чергу.</p><details><summary>Позиції, що потребують уваги</summary><p v-if="!data.attention.length">Таких позицій зараз немає.</p><article v-for="p in data.attention" :key="p.productId" class="work-item"><strong>№{{ p.orderNo }} · {{ p.productName }}</strong><p>{{ p.branchName }} · строк: {{ p.dueDate ? String(p.dueDate).slice(0,10) : 'не вказано' }}</p><div class="flags"><span v-if="truth(p.late)">Минув строк готовності</span><span v-if="truth(p.approval)">Погодження ціни</span><span v-if="truth(p.shortage)">Дефіцит матеріалів</span></div><OrderHistory :session="session" :order-no="p.orderNo" /></article><p v-if="data.moreAttention">Показано перші 20 позицій за строком готовності. Повні робочі черги — у «Моїх завданнях».</p></details><h3 v-if="data.mode !== 'RESELLER'">Результат виданих виробів власних філій</h3><p v-if="data.financialError" role="alert">Фінансовий результат не завантажено: {{ data.financialError }}</p><template v-if="data.ownResults"><div class="metrics"><article><span>Відомі суми реалізації</span><strong>{{ money(data.ownResults.knownSales) }} грн</strong></article><article><span>Відома собівартість матеріалів</span><strong>{{ money(data.ownResults.knownMaterials) }} грн</strong></article><article><span>Нараховані винагороди</span><strong>{{ money(data.ownResults.rewards) }} грн</strong></article><article><span>Різниця після матеріалів і винагород</span><strong>{{ money(data.ownResults.difference) }}{{ data.ownResults.difference == null ? '' : ' грн' }}</strong></article></div><p v-if="data.ownResults.incompleteCount" role="status">Неповні дані для {{ data.ownResults.incompleteCount }} позицій: без визначеної реалізації — {{ data.ownResults.unknownSales }}, без повної собівартості — {{ data.ownResults.unknownMaterials }}, винагорода потребує перевірки — {{ data.ownResults.pendingRewards }}. Підсумкова різниця не визначена.</p><p class="help">Той самий розрахунок, що у «Звіти → Власні філії», за першою видачею клієнту. Це не чистий прибуток і не залишок грошей: оренда, комунальні витрати та інші витрати підприємства тут не відняті. Гроші кінцевих клієнтів посередників сюди не входять.</p></template><p v-if="data.mode === 'RESELLER'">Розрахунки з посередниками дивіться у відповідних рахунках і звіті фірм-посередників. Роздрібні оплати їхніх клієнтів не є надходженнями підприємства.</p><details><summary>Що враховано</summary><p>Огляд виробництва охоплює замовлення з картками виробів нового формату. Для завершення потрібна збережена подія завершення, для видачі — подія приймання клієнтом; давні дії без таких записів не відновлюються. Оформлені за період замовлення враховуються навіть якщо згодом скасовані. Тип філії береться зі збереженого типу замовлення; невизначений тип входить лише до «Усі».</p></details></template></section></template>
<style scoped>.management{min-width:0}header,.actions{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}h2{margin:0}.filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) auto;align-items:end;gap:12px;margin:16px 0}.filters label{display:grid;gap:6px;min-width:0}button,input,select{font:inherit;min-height:44px;padding:9px;border:1px solid #bdcdd5;border-radius:7px;max-width:100%;box-sizing:border-box}button{cursor:pointer;background:white}button:disabled{opacity:.5}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.metrics article,.branch-grid article,.work-item{padding:14px;border:1px solid #d1dce3;border-radius:10px;min-width:0;overflow-wrap:anywhere}.metrics article{display:grid;gap:10px;background:#f5f9fa}.metrics strong{font-size:26px;font-variant-numeric:tabular-nums}.metrics span{color:#4b606a}.metrics .attention{border-color:#d4a661;background:#fff9ec}.help,.context{color:#536773;line-height:1.5}.branch-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:10px}h4{margin:0}details{margin:18px 0}summary{cursor:pointer;padding:10px 0;min-height:44px;box-sizing:border-box;font-weight:600}.work-item{margin:10px 0}.flags{display:flex;gap:8px;flex-wrap:wrap}.flags span{padding:4px 8px;background:#fff0d3;border-radius:6px}[role=alert]{color:#a22}@media(max-width:950px){.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.filters button{grid-column:1/-1}}@media(max-width:550px){.filters,.metrics,.branch-grid{grid-template-columns:1fr}input,select{font-size:16px;width:100%}.metrics strong{font-size:24px}}</style>
